/// Parses a prefix operator, if there is one and its precedence is at least
/// min_precedence.
fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
    match self.peek().ok().flatten() {
        Some(Token::Minus) if min_precedence <= PrefixOperator::Minus.precedence() => {
            self.next().ok()?;
            Some(PrefixOperator::Minus)
        }
        Some(Token::Plus) if min_precedence <= PrefixOperator::Plus.precedence() => {
            self.next().ok()?;
            Some(PrefixOperator::Plus)
        }
        Some(Token::Keyword(Keyword::Not)) if min_precedence <= PrefixOperator::Not.precedence() => {
            self.next().ok()?;
            Some(PrefixOperator::Not)
        }
        _ => None,
    }
}
